style.css:
@-moz-document domain("chess.com") {
/* Substitui as casas brancas por preto no board rosa */
.board {
    background-color: #000 !important; /* cor do fundo do board */
}

.board .square.white {
    background-color: #000 !important; /* casas que eram brancas viram preto */
}

.board .square.black {
    background-color: #ffb6c1 !important; /* mantém o rosa original nas casas pretas */
}
}
